import numpy as np,json
s=json.load(open('/app/output/spec.json'));c=s['cameras']['room_camera'];p=c['pose'];C=np.array(p['position_m']);F=np.array(p['forward']);U=np.array(p['up']);R=np.array(p['right']);f=128/np.tan(np.deg2rad(c['fovy_deg']/2))
def ray(u,v):return F+(u-128)/f*R-(v-128)/f*U
def ground(u,v,z=0):
 d=ray(u,v);return C+(z-C[2])/d[2]*d
def project(pt):
 d=np.array(pt)-C;return [128+f*np.dot(d,R)/np.dot(d,F),128-f*np.dot(d,U)/np.dot(d,F)]
if __name__=='__main__':
 for a in [(93,211,0),(177,189,0),(75,153,1),(151,135,1),(93,128,1.2),(120,124,1.2),(186,167,1),(240,172,1)]:print(a,ground(*a))
 print('origin',project([0,0,0]),'pelvis',project([0,0,1]),'box',project([2,0,1.2]))
